// ─── SAVE DATA ───────────────────────────────────────────
interface SaveData {
  bestScore: number; bestWave: number; totalInterceptions: number;
  gamesPlayed: number; perfectWaves: number; bestMultiKill: number;
  mirvsDestroyed: number; smartsDestroyed: number; bombersDestroyed: number;
  dailyCompleted: number; modesPlayed: number; themesUsed: number;
  citiesSaved: number; perfectAccuracyWaves: number; chainBlasts: number;
  level: number; xp: number; survivalBest: number; blitzBest: number;
  totalScore: number; totalShots: number; totalCitiesLost: number;
  achievements: string[]; theme: number; skin: number;
  masterVol: number; sfxVol: number; musicVol: number;
  modesSet: string[]; themesSet: string[];
  leaderboard: { score: number; wave: number; mode: string; date: string }[];
}

function defaultSave(): SaveData {
  return {
    bestScore: 0, bestWave: 0, totalInterceptions: 0, gamesPlayed: 0,
    perfectWaves: 0, bestMultiKill: 0, mirvsDestroyed: 0, smartsDestroyed: 0,
    bombersDestroyed: 0, dailyCompleted: 0, modesPlayed: 0, themesUsed: 0,
    citiesSaved: 0, perfectAccuracyWaves: 0, chainBlasts: 0,
    level: 1, xp: 0, survivalBest: 0, blitzBest: 0,
    totalScore: 0, totalShots: 0, totalCitiesLost: 0,
    achievements: [], theme: 0, skin: 0,
    masterVol: 0.8, sfxVol: 0.8, musicVol: 0.5,
    modesSet: [], themesSet: [], leaderboard: [],
  };
}

function loadSave(): SaveData {
  try { const d = localStorage.getItem('neon-command-save'); if (d) { const p = JSON.parse(d); return { ...defaultSave(), ...p }; } } catch {}
  return defaultSave();
}

function saveSave(s: SaveData) {
  try { localStorage.setItem('neon-command-save', JSON.stringify(s)); } catch {}
}

// ─── GAME STATE ──────────────────────────────────────────
