  sx: number; sy: number; tx: number; ty: number;
  speed: number; progress: number;
  type: 'normal' | 'mirv' | 'smart' | 'bomber';
  alive: boolean; splitDone: boolean;
}

// ─── COUNTER MISSILE ─────────────────────────────────────
interface CounterMissile {
  mesh: Mesh; trail: Line; trailPts: Vector3[];
  sx: number; sy: number; tx: number; ty: number;
  speed: number; progress: number; alive: boolean;
}

// ─── BLAST ───────────────────────────────────────────────
interface Blast {
  mesh: Mesh; glow: Mesh;
  x: number; y: number;
  radius: number; maxRadius: number;
  phase: 'expanding' | 'holding' | 'shrinking';
  timer: number; alive: boolean;
}

