}

// ─── BASE ────────────────────────────────────────────────
interface Base {
  group: Group; ammo: number; maxAmmo: number; x: number;
}

// ─── PARTICLE ────────────────────────────────────────────
interface Particle {
  mesh: Mesh; vx: number; vy: number; vz: number; life: number; maxLife: number; active: boolean;
}

// ─── AUDIO ───────────────────────────────────────────────
class AudioEngine {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private sfxGain: GainNode | null = null;
  private musicGain: GainNode | null = null;
  private droneOscs: OscillatorNode[] = [];
  private arpOsc: OscillatorNode | null = null;
  private arpGain: GainNode | null = null;
  private arpInterval: ReturnType<typeof setInterval> | null = null;

  init(masterVol: number, sfxVol: number, musicVol: number) {
    if (this.ctx) return;
    this.ctx = new AudioContext();
    this.masterGain = this.ctx.createGain();
    this.masterGain.gain.value = masterVol;
    this.masterGain.connect(this.ctx.destination);
    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = sfxVol;
    this.sfxGain.connect(this.masterGain);
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = musicVol;
    this.musicGain.connect(this.masterGain);
  }

  setVolumes(master: number, sfx: number, music: number) {
    if (this.masterGain) this.masterGain.gain.value = master;
    if (this.sfxGain) this.sfxGain.gain.value = sfx;
    if (this.musicGain) this.musicGain.gain.value = music;
  }

  private playSfx(freq: number, type: OscillatorType, dur: number, vol = 0.3) {
    if (!this.ctx || !this.sfxGain) return;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type;
    o.frequency.value = freq * (0.95 + Math.random() * 0.1);
    g.gain.value = vol;
    g.gain.exponentialRampToValueAtTime(0.001, this.ctx.currentTime + dur);
    o.connect(g).connect(this.sfxGain);
    o.start(); o.stop(this.ctx.currentTime + dur);
  }

  fire() { this.playSfx(880, 'triangle', 0.15, 0.25); this.playSfx(660, 'sine', 0.1, 0.15); }
  blast() { this.playSfx(220, 'sawtooth', 0.4, 0.35); this.playSfx(110, 'square', 0.5, 0.2); }
  intercept() { this.playSfx(1100, 'sine', 0.12, 0.2); this.playSfx(1320, 'triangle', 0.1, 0.15); }
  cityHit() { this.playSfx(80, 'sawtooth', 0.6, 0.4); this.playSfx(60, 'square', 0.8, 0.3); }
  waveClear() {
    [660, 880, 1100, 1320, 1650].forEach((f, i) => {
      setTimeout(() => this.playSfx(f, 'sine', 0.25, 0.2), i * 80);
    });
  }
  gameOver() {
    [440, 330, 220, 165].forEach((f, i) => {
      setTimeout(() => this.playSfx(f, 'triangle', 0.3, 0.25), i * 120);
    });
  }
  click() { this.playSfx(1000, 'sine', 0.05, 0.15); }
  achievement() {
    [880, 1100, 1320, 1540, 1760].forEach((f, i) => {
      setTimeout(() => this.playSfx(f, 'sine', 0.2, 0.15), i * 60);
    });
  }
  countdown() { this.playSfx(660, 'sine', 0.1, 0.2); }
  countdownGo() { this.playSfx(1320, 'sine', 0.2, 0.25); }
  mirvSplit() { this.playSfx(440, 'sawtooth', 0.2, 0.2); this.playSfx(550, 'triangle', 0.15, 0.15); }
  bomberPass() { this.playSfx(150, 'square', 0.3, 0.15); }
  levelUp() {
    [660, 880, 1100, 1320, 1540, 1760].forEach((f, i) => {
      setTimeout(() => this.playSfx(f, 'triangle', 0.2, 0.18), i * 50);
    });
  }

  startMusic() {
    if (!this.ctx || !this.musicGain) return;
    this.stopMusic();
    const freqs = [55, 82.5, 110];
    this.droneOscs = freqs.map((f, i) => {
      const o = this.ctx!.createOscillator();
      const g = this.ctx!.createGain();
      const lp = this.ctx!.createBiquadFilter();
      o.type = i === 0 ? 'sine' : i === 1 ? 'triangle' : 'sine';
      o.frequency.value = f;
      g.gain.value = 0.12;
      lp.type = 'lowpass'; lp.frequency.value = 400;
      o.connect(lp).connect(g).connect(this.musicGain!);
      o.start();
      return o;
    });
    // LFO
    const lfo = this.ctx.createOscillator();
    const lfoG = this.ctx.createGain();
    lfo.type = 'sine'; lfo.frequency.value = 0.15;
    lfoG.gain.value = 30;
    lfo.connect(lfoG);
    if (this.droneOscs[0]) lfoG.connect(this.droneOscs[0].frequency);
    lfo.start();
    this.droneOscs.push(lfo);
    // Arp
    const notes = [220, 330, 440, 330];
    let ni = 0;
    this.arpOsc = this.ctx.createOscillator();
    this.arpGain = this.ctx.createGain();
    this.arpOsc.type = 'square';
    this.arpOsc.frequency.value = notes[0];
    this.arpGain.gain.value = 0.06;
    const arpLp = this.ctx.createBiquadFilter();
    arpLp.type = 'lowpass'; arpLp.frequency.value = 600;
    this.arpOsc.connect(arpLp).connect(this.arpGain).connect(this.musicGain!);
    this.arpOsc.start();
    this.arpInterval = setInterval(() => {
      ni = (ni + 1) % notes.length;
      if (this.arpOsc) this.arpOsc.frequency.value = notes[ni];
    }, 545);
  }

  stopMusic() {
    this.droneOscs.forEach(o => { try { o.stop(); } catch {} });
    this.droneOscs = [];
    if (this.arpOsc) { try { this.arpOsc.stop(); } catch {} this.arpOsc = null; }
    if (this.arpInterval) { clearInterval(this.arpInterval); this.arpInterval = null; }
  }
}

// ─── SEEDED PRNG ─────────────────────────────────────────
function mulberry32(a: number) {
  return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t ^= t + Math.imul(t ^ t >>> 7, 61 | t); return ((t ^ t >>> 14) >>> 0) / 4294967296; };
}

function dateSeed(): number {
  const d = new Date();
  return d.getFullYear() * 10000 + (d.getMonth() + 1) * 100 + d.getDate();
}

