// ─── CITY AND BASE SETUP ────────────────────────────────
const CITY_POSITIONS = [-4.5, -2.7, -0.9, 0.9, 2.7, 4.5];
const BASE_POSITIONS = [-3.6, 0, 3.6];
const PLAY_Z = -8;
const GROUND_Y = 0.5;
const SKY_Y = 8;

function createCity(x: number): City {
  const g = new Group();
  // Main building
  const b1 = new Mesh(new BoxGeometry(0.3, 0.5, 0.3), new MeshBasicMaterial({ color: theme.city, transparent: true, opacity: 0.7 }));
  const e1 = new LineSegments(new EdgesGeometry(b1.geometry), new LineBasicMaterial({ color: theme.city }));
  b1.position.y = 0.25; e1.position.y = 0.25;
  // Side towers
  const b2 = new Mesh(new BoxGeometry(0.2, 0.35, 0.2), new MeshBasicMaterial({ color: theme.city, transparent: true, opacity: 0.5 }));
  const e2 = new LineSegments(new EdgesGeometry(b2.geometry), new LineBasicMaterial({ color: theme.city }));
  b2.position.set(-0.2, 0.175, 0); e2.position.set(-0.2, 0.175, 0);
  const b3 = new Mesh(new BoxGeometry(0.2, 0.4, 0.2), new MeshBasicMaterial({ color: theme.city, transparent: true, opacity: 0.5 }));
  const e3 = new LineSegments(new EdgesGeometry(b3.geometry), new LineBasicMaterial({ color: theme.city }));
  b3.position.set(0.2, 0.2, 0); e3.position.set(0.2, 0.2, 0);
  // Glow
  const glow = new Mesh(new SphereGeometry(0.35, 8, 8), new MeshBasicMaterial({ color: theme.city, transparent: true, opacity: 0.15, blending: AdditiveBlending }));
  glow.position.y = 0.3;
  g.add(b1, e1, b2, e2, b3, e3, glow);
  g.position.set(x, GROUND_Y, PLAY_Z);
  playfield.add(g);
  return { group: g, alive: true, x };
}

function createBase(x: number, maxAmmo: number): Base {
  const g = new Group();
  const body = new Mesh(new CylinderGeometry(0.2, 0.3, 0.3, 8), new MeshBasicMaterial({ color: theme.base, transparent: true, opacity: 0.7 }));
  const edges = new LineSegments(new EdgesGeometry(body.geometry), new LineBasicMaterial({ color: theme.base }));
  body.position.y = 0.15; edges.position.y = 0.15;
  const turret = new Mesh(new SphereGeometry(0.12, 8, 8), new MeshBasicMaterial({ color: theme.base }));
  turret.position.y = 0.35;
  const glow = new Mesh(new SphereGeometry(0.25, 8, 8), new MeshBasicMaterial({ color: theme.base, transparent: true, opacity: 0.2, blending: AdditiveBlending }));
  glow.position.y = 0.25;
  g.add(body, edges, turret, glow);
  g.position.set(x, GROUND_Y, PLAY_Z);
  playfield.add(g);
  return { group: g, ammo: maxAmmo, maxAmmo, x };
}

// ─── PARTICLE SYSTEM ─────────────────────────────────────
function initParticles() {
  for (let i = 0; i < 150; i++) {
    const m = new Mesh(new SphereGeometry(0.03, 4, 4), new MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0, blending: AdditiveBlending }));
    m.visible = false;
    playfield.add(m);
    particles.push({ mesh: m, vx: 0, vy: 0, vz: 0, life: 0, maxLife: 0, active: false });
  }
}

function spawnParticles(x: number, y: number, z: number, color: string, count: number) {
  let spawned = 0;
  for (const p of particles) {
    if (p.active || spawned >= count) continue;
    p.active = true;
    p.mesh.visible = true;
    p.mesh.position.set(x, y, z);
    (p.mesh.material as MeshBasicMaterial).color.set(color);
    (p.mesh.material as MeshBasicMaterial).opacity = 1;
    const angle = Math.random() * Math.PI * 2;
    const speed = 1 + Math.random() * 3;
    const elev = (Math.random() - 0.3) * Math.PI;
    p.vx = Math.cos(angle) * Math.cos(elev) * speed;
    p.vy = Math.sin(elev) * speed + 1;
    p.vz = Math.sin(angle) * Math.cos(elev) * speed * 0.3;
    p.life = 0;
    p.maxLife = 0.5 + Math.random() * 0.8;
    spawned++;
  }
}

initParticles();

// ─── ENEMY MISSILE CREATION ─────────────────────────────
function spawnEnemyMissile(sx: number, sy: number, tx: number, ty: number, speed: number, type: EnemyMissile['type'] = 'normal') {
  const color = type === 'mirv' ? theme.mirv : type === 'smart' ? theme.smart : theme.enemy;
  const geo = type === 'mirv' ? new OctahedronGeometry(0.06) : type === 'smart' ? new ConeGeometry(0.04, 0.1, 6) : new SphereGeometry(0.04, 6, 6);
  const mesh = new Mesh(geo, new MeshBasicMaterial({ color, emissive: new Color(color), emissiveIntensity: 0.5 }));
  mesh.position.set(sx, sy, PLAY_Z);
  playfield.add(mesh);
  // Trail
  const pts: Vector3[] = [];
  for (let i = 0; i < 20; i++) pts.push(new Vector3(sx, sy, PLAY_Z));
  const tGeo = new BufferGeometry().setFromPoints(pts);
  const trail = new Line(tGeo, new LineBasicMaterial({ color, transparent: true, opacity: 0.4 }));
  playfield.add(trail);
  enemyMissiles.push({ mesh, trail, trailPts: pts, sx, sy, tx, ty, speed, progress: 0, type, alive: true, splitDone: false });
}

function spawnBomber(y: number, speed: number) {
  const mesh = new Mesh(new BoxGeometry(0.15, 0.06, 0.06), new MeshBasicMaterial({ color: theme.enemy }));
  const fromLeft = Math.random() > 0.5;
  const sx = fromLeft ? -6 : 6;
  const tx = fromLeft ? 6 : -6;
  mesh.position.set(sx, y, PLAY_Z);
  playfield.add(mesh);
  const pts: Vector3[] = [];
  for (let i = 0; i < 20; i++) pts.push(new Vector3(sx, y, PLAY_Z));
  const tGeo = new BufferGeometry().setFromPoints(pts);
  const trail = new Line(tGeo, new LineBasicMaterial({ color: theme.enemy, transparent: true, opacity: 0.3 }));
  playfield.add(trail);
  enemyMissiles.push({ mesh, trail, trailPts: pts, sx, sy: y, tx, ty: y, speed, progress: 0, type: 'bomber', alive: true, splitDone: false });
}

// ─── COUNTER MISSILE ─────────────────────────────────────
function fireCounterMissile(tx: number, ty: number): boolean {
  // Find nearest base with ammo
  let best: Base | null = null;
  let bestDist = Infinity;
  for (const b of bases) {
    if (b.ammo <= 0) continue;
    const d = Math.abs(b.x - tx);
    if (d < bestDist) { bestDist = d; best = b; }
  }
  if (!best) return false;
  best.ammo--;
  const mesh = new Mesh(new SphereGeometry(0.03, 6, 6), new MeshBasicMaterial({ color: theme.missile }));
  mesh.position.set(best.x, GROUND_Y + 0.4, PLAY_Z);
  playfield.add(mesh);
  const pts: Vector3[] = [];
  for (let i = 0; i < 15; i++) pts.push(new Vector3(best.x, GROUND_Y + 0.4, PLAY_Z));
  const tGeo = new BufferGeometry().setFromPoints(pts);
  const trail = new Line(tGeo, new LineBasicMaterial({ color: theme.missile, transparent: true, opacity: 0.5 }));
  playfield.add(trail);
  counterMissiles.push({
    mesh, trail, trailPts: pts,
    sx: best.x, sy: GROUND_Y + 0.4, tx, ty,
    speed: 6, progress: 0, alive: true,
  });
  audio.fire();
  shotsFiredThisWave++;
  return true;
}

// ─── BLAST CREATION ──────────────────────────────────────
function createBlast(x: number, y: number, maxRadius = 0.6) {
  const mesh = new Mesh(new SphereGeometry(0.1, 16, 16), new MeshBasicMaterial({ color: theme.blast, transparent: true, opacity: 0.6 }));
  const glow = new Mesh(new SphereGeometry(0.15, 16, 16), new MeshBasicMaterial({ color: theme.blast, transparent: true, opacity: 0.3, blending: AdditiveBlending }));
  mesh.position.set(x, y, PLAY_Z);
  glow.position.set(x, y, PLAY_Z);
  playfield.add(mesh, glow);
  blasts.push({ mesh, glow, x, y, radius: 0.1, maxRadius, phase: 'expanding', timer: 0, alive: true });
  audio.blast();
}

// ─── WAVE GENERATION ─────────────────────────────────────
function generateWave(waveNum: number, rng?: () => number) {
  const r = rng || Math.random;
  const count = Math.min(4 + waveNum * 2, 30);
  const speed = 0.5 + waveNum * 0.08;
  const mirvChance = waveNum >= 3 ? Math.min(0.1 + (waveNum - 3) * 0.03, 0.3) : 0;
  const smartChance = waveNum >= 5 ? Math.min(0.05 + (waveNum - 5) * 0.02, 0.2) : 0;
  const bomberChance = waveNum >= 7 ? Math.min(0.05 + (waveNum - 7) * 0.015, 0.15) : 0;
  const aliveCities = cities.filter(c => c.alive);
  if (aliveCities.length === 0) return;

  for (let i = 0; i < count; i++) {
    const delay = i * (0.3 + r() * 0.5);
    setTimeout(() => {
      if (state !== 'playing') return;
      const roll = r();
      if (roll < bomberChance) {
        spawnBomber(3 + r() * 4, 1.5 + r() * 1.5);
        return;
      }
      const sx = -5 + r() * 10;
      const target = aliveCities[Math.floor(r() * aliveCities.length)];
      const ty = GROUND_Y;
      const type: EnemyMissile['type'] = roll < bomberChance + smartChance ? 'smart' : roll < bomberChance + smartChance + mirvChance ? 'mirv' : 'normal';
      const s = speed * (0.8 + r() * 0.4) * (type === 'smart' ? 1.3 : 1);
      spawnEnemyMissile(sx, SKY_Y + r() * 2, target.x, ty, s, type);
    }, delay * 1000);
  }
}

// ─── SETUP GAME ──────────────────────────────────────────
function setupGame() {
  // Clear old objects
  for (const e of enemyMissiles) { playfield.remove(e.mesh); playfield.remove(e.trail); }
  for (const c of counterMissiles) { playfield.remove(c.mesh); playfield.remove(c.trail); }
  for (const b of blasts) { playfield.remove(b.mesh); playfield.remove(b.glow); }
  for (const c of cities) playfield.remove(c.group);
  for (const b of bases) playfield.remove(b.group);
  enemyMissiles.length = 0;
  counterMissiles.length = 0;
  blasts.length = 0;
  cities.length = 0;
  bases.length = 0;

  score = 0; wave = 0; gameTime = 0; blitzTimer = 60;
  shotsFiredThisWave = 0; interceptsThisWave = 0;

  // Create cities
  for (const x of CITY_POSITIONS) cities.push(createCity(x));
  citiesAliveStart = 6;

  // Create bases
  const ammoByDiff = difficulty === 'easy' ? 15 : difficulty === 'medium' ? 10 : 7;
  if (mode === 'turret') {
    bases.push(createBase(0, 999));
  } else if (mode === 'practice') {
    for (const x of BASE_POSITIONS) bases.push(createBase(x, 999));
  } else {
    for (const x of BASE_POSITIONS) bases.push(createBase(x, ammoByDiff));
  }

  // Track mode
  if (!save.modesSet.includes(mode)) {
    save.modesSet.push(mode);
    save.modesPlayed = save.modesSet.length;
  }
  if (!save.themesSet.includes(theme.name)) {
    save.themesSet.push(theme.name);
    save.themesUsed = save.themesSet.length;
  }
}

function startWave() {
  wave++;
  shotsFiredThisWave = 0;
  interceptsThisWave = 0;
  citiesAliveStart = cities.filter(c => c.alive).length;
  // Refill ammo
  const ammoByDiff = difficulty === 'easy' ? 15 : difficulty === 'medium' ? 10 : 7;
  for (const b of bases) {
    if (mode !== 'turret' && mode !== 'practice') {
      b.ammo = b.maxAmmo;
    }
  }
  if (mode === 'daily') {
    const rng = mulberry32(dateSeed() + wave);
    generateWave(wave, rng);
  } else {
    generateWave(wave);
  }
}

// ─── CHECK WAVE END ──────────────────────────────────────
function checkWaveEnd(): boolean {
  if (enemyMissiles.some(e => e.alive)) return false;
  if (counterMissiles.some(c => c.alive)) return false;
  if (blasts.some(b => b.alive)) return false;
  return true;
}

// ─── XP / LEVEL ──────────────────────────────────────────
function addXp(amount: number) {
  save.xp += amount;
  const needed = 100 + save.level * 50;
  if (save.xp >= needed) {
    save.xp -= needed;
    save.level++;
    audio.levelUp();
    showToast('LEVEL UP! Lv.' + save.level);
  }
}

// ─── TOAST SYSTEM ────────────────────────────────────────
let toastText = '';
let toastTimer = 0;

function showToast(text: string) {
  toastText = text;
  toastTimer = 2.5;
}

// ─── CHECK ACHIEVEMENTS ─────────────────────────────────
function checkAchievements() {
  for (const a of ACHIEVEMENTS) {
    if (save.achievements.includes(a.id)) continue;
    if (a.check(save)) {
      save.achievements.push(a.id);
      audio.achievement();
      showToast('Achievement: ' + a.name);
    }
  }
}

// ─── GAME SYSTEMS ────────────────────────────────────────
export class CommandGameSystem extends createSystem({}) {
  update(delta: number, _time: number) {
    if (state !== 'playing') {
      // Countdown
      if (countdownTimer > 0) {
        countdownTimer -= delta;
        const newVal = Math.ceil(countdownTimer);
        if (newVal !== countdownVal && newVal > 0) {
          countdownVal = newVal;
          audio.countdown();
        }
        if (countdownTimer <= 0) {
          state = 'playing';
          crosshairGroup.visible = true;
          audio.countdownGo();
          audio.startMusic();
          startWave();
        }
      }
      // Update particles
      updateParticles(delta);
      // Animate decorations
      animateDecorations(delta, _time);
      return;
    }

    gameTime += delta;
    if (mode === 'blitz') {
      blitzTimer -= delta;
      if (blitzTimer <= 0) {
        endGame();
        return;
      }
    }

    // Mouse/controller input for aiming
    handleInput();

    // Update enemy missiles
    updateEnemyMissiles(delta);

    // Update counter missiles
    updateCounterMissiles(delta);

    // Update blasts
    updateBlasts(delta);

    // Update particles
    updateParticles(delta);

    // Animate decorations
    animateDecorations(delta, _time);

    // Check game over
    if (!cities.some(c => c.alive) && mode !== 'practice') {
      endGame();
      return;
    }

    // Check wave clear
    if (checkWaveEnd()) {
      const citiesAlive = cities.filter(c => c.alive).length;
      const cityBonus = citiesAlive * 100;
      const ammoBonus = bases.reduce((s, b) => s + b.ammo, 0) * 5;
      score += cityBonus + ammoBonus;
      save.citiesSaved += citiesAlive;
      if (citiesAlive === citiesAliveStart) {
        save.perfectWaves++;
      }
      if (shotsFiredThisWave > 0 && interceptsThisWave >= shotsFiredThisWave) {
        // Not meaningful — skip
      }
      if (shotsFiredThisWave > 0 && interceptsThisWave > 0) {
        const accuracy = interceptsThisWave / shotsFiredThisWave;
        if (accuracy >= 1) save.perfectAccuracyWaves++;
      }

      if (mode === 'classic' && wave >= 20) { endGame(); return; }
      if (mode === 'marathon' && wave >= 50) { endGame(); return; }
      if (mode === 'wave_defense' && wave >= 10) { endGame(); return; }
      if (mode === 'daily' && wave >= 15) {
        save.dailyCompleted++;
        endGame();
        return;
      }

      audio.waveClear();
      state = 'waveclear';
      waveClearTimer = 2.5;
    }
  }
}

function handleInput() {
  // Browser: mouse click to fire
  const kb = (world.input as any)?.keyboard;
  if (kb) {
    if (kb.getKeyDown?.('Space') || kb.getKeyDown?.('KeyF')) {
      const cx = crosshairGroup.position.x;
      const cy = crosshairGroup.position.y;
      if (cy > GROUND_Y + 0.5) {
        fireCounterMissile(cx, cy);
      }
    }
  }
}

function updateEnemyMissiles(delta: number) {
  for (const e of enemyMissiles) {
    if (!e.alive) continue;

    if (e.type === 'bomber') {
      // Horizontal movement
      e.progress += delta * e.speed / 12;
      const x = e.sx + (e.tx - e.sx) * e.progress;
      e.mesh.position.set(x, e.sy, PLAY_Z);
      // Drop bombs occasionally
      if (Math.random() < 0.01 * delta * 60) {
        const aliveCities = cities.filter(c => c.alive);
        if (aliveCities.length > 0) {
          const target = aliveCities[Math.floor(Math.random() * aliveCities.length)];
          spawnEnemyMissile(x, e.sy, target.x, GROUND_Y, 1.5);
        }
      }
      if (e.progress >= 1) {
        e.alive = false;
        e.mesh.visible = false;
        e.trail.visible = false;
      }
    } else {
      e.progress += delta * e.speed / 10;
      let x = e.sx + (e.tx - e.sx) * e.progress;
      let y = e.sy + (e.ty - e.sy) * e.progress;

      // Smart missile zigzag
      if (e.type === 'smart') {
        x += Math.sin(e.progress * 20) * 0.3;
        // Dodge nearby blasts
        for (const b of blasts) {
          if (!b.alive) continue;
          const dx = x - b.x;
          const dy = y - b.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < b.radius + 0.5) {
            x += (dx / dist) * 2 * delta;
          }
        }
      }

      // MIRV split
      if (e.type === 'mirv' && !e.splitDone && e.progress > 0.4) {
        e.splitDone = true;
        audio.mirvSplit();
        const aliveCities = cities.filter(c => c.alive);
        for (let i = 0; i < 3; i++) {
          const target = aliveCities.length > 0 ? aliveCities[Math.floor(Math.random() * aliveCities.length)] : cities[Math.floor(Math.random() * cities.length)];
          spawnEnemyMissile(x, y, target.x + (Math.random() - 0.5) * 0.5, GROUND_Y, e.speed * 1.2, 'normal');
        }
        spawnParticles(x, y, PLAY_Z, theme.mirv, 8);
        e.alive = false;
        e.mesh.visible = false;
        e.trail.visible = false;
        continue;
      }

      e.mesh.position.set(x, y, PLAY_Z);

      // Update trail
      e.trailPts.pop();
      e.trailPts.unshift(new Vector3(x, y, PLAY_Z));
      (e.trail.geometry as BufferGeometry).setFromPoints(e.trailPts);

      // Check if hit city
      if (e.progress >= 1) {
        e.alive = false;
        e.mesh.visible = false;
        e.trail.visible = false;
        if (mode !== 'practice') {
          // Find nearest city
          let nearestCity: City | null = null;
          let nearDist = Infinity;
          for (const c of cities) {
            if (!c.alive) continue;
            const d = Math.abs(c.x - e.tx);
            if (d < nearDist) { nearDist = d; nearestCity = c; }
          }
          if (nearestCity && nearDist < 1) {
            nearestCity.alive = false;
            nearestCity.group.visible = false;
            save.totalCitiesLost++;
            audio.cityHit();
            spawnParticles(nearestCity.x, GROUND_Y + 0.3, PLAY_Z, theme.city, 20);
          }
        }
        spawnParticles(e.tx, e.ty, PLAY_Z, theme.enemy, 8);
      }
    }
  }
}

function updateCounterMissiles(delta: number) {
  for (const c of counterMissiles) {
    if (!c.alive) continue;
    const dx = c.tx - c.sx;
    const dy = c.ty - c.sy;
    const dist = Math.sqrt(dx * dx + dy * dy);
    c.progress += delta * c.speed / dist;
    const x = c.sx + dx * c.progress;
    const y = c.sy + dy * c.progress;
    c.mesh.position.set(x, y, PLAY_Z);

    // Trail
    c.trailPts.pop();
    c.trailPts.unshift(new Vector3(x, y, PLAY_Z));
    (c.trail.geometry as BufferGeometry).setFromPoints(c.trailPts);

    if (c.progress >= 1) {
      c.alive = false;
      c.mesh.visible = false;
      c.trail.visible = false;
      createBlast(c.tx, c.ty);
      save.totalShots++;
    }
  }
}

function updateBlasts(delta: number) {
  for (const b of blasts) {
    if (!b.alive) continue;
    b.timer += delta;

    if (b.phase === 'expanding') {
      b.radius += delta * 2.5;
      if (b.radius >= b.maxRadius) {
        b.radius = b.maxRadius;
        b.phase = 'holding';
        b.timer = 0;
      }
    } else if (b.phase === 'holding') {
      if (b.timer > 0.5) {
        b.phase = 'shrinking';
        b.timer = 0;
      }
    } else {
      b.radius -= delta * 2;
      if (b.radius <= 0) {
        b.alive = false;
        b.mesh.visible = false;
        b.glow.visible = false;
        continue;
      }
    }

    b.mesh.scale.setScalar(b.radius / 0.1);
    b.glow.scale.setScalar(b.radius / 0.15 * 1.3);
    (b.mesh.material as MeshBasicMaterial).opacity = b.phase === 'shrinking' ? 0.3 + b.radius / b.maxRadius * 0.3 : 0.6;
    (b.glow.material as MeshBasicMaterial).opacity = b.radius / b.maxRadius * 0.3;

    // Check interceptions
    let killsThisBlast = 0;
    for (const e of enemyMissiles) {
      if (!e.alive) continue;
      const dx = e.mesh.position.x - b.x;
      const dy = e.mesh.position.y - b.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < b.radius) {
        e.alive = false;
        e.mesh.visible = false;
        e.trail.visible = false;
        save.totalInterceptions++;
        interceptsThisWave++;
        killsThisBlast++;
        const pts = e.type === 'mirv' ? 50 : e.type === 'smart' ? 75 : e.type === 'bomber' ? 100 : 25;
        score += pts;
        addXp(pts / 5);
        if (e.type === 'mirv' && !e.splitDone) save.mirvsDestroyed++;
        if (e.type === 'smart') save.smartsDestroyed++;
        if (e.type === 'bomber') save.bombersDestroyed++;
        audio.intercept();
        spawnParticles(e.mesh.position.x, e.mesh.position.y, PLAY_Z, theme.blast, 10);

        // Chain blast: destroyed missile creates a smaller blast
        if (killsThisBlast >= 2) {
          save.chainBlasts++;
          createBlast(e.mesh.position.x, e.mesh.position.y, 0.35);
        }
      }
    }
    if (killsThisBlast > multiKillCount) multiKillCount = killsThisBlast;
    if (killsThisBlast > save.bestMultiKill) save.bestMultiKill = killsThisBlast;
  }
}

function updateParticles(delta: number) {
  for (const p of particles) {
    if (!p.active) continue;
    p.life += delta;
    if (p.life >= p.maxLife) {
      p.active = false;
      p.mesh.visible = false;
      continue;
    }
    p.mesh.position.x += p.vx * delta;
    p.mesh.position.y += p.vy * delta;
    p.mesh.position.z += p.vz * delta;
    p.vy -= 3 * delta;
    const t = 1 - p.life / p.maxLife;
    (p.mesh.material as MeshBasicMaterial).opacity = t;
    p.mesh.scale.setScalar(t);
  }
}

function animateDecorations(delta: number, time: number) {
  playfield.children.forEach(child => {
    if (child instanceof LineSegments && child.userData.rotSpeed) {
      child.rotation.y += child.userData.rotSpeed * delta;
      child.rotation.x += child.userData.rotSpeed * 0.3 * delta;
      child.position.y += Math.sin(time * 0.5 + (child.userData.bobOffset || 0)) * 0.001;
    }
  });
  // Toast timer
  if (toastTimer > 0) toastTimer -= delta;
  // Wave clear timer
  if (state === 'waveclear') {
    waveClearTimer -= delta;
    if (waveClearTimer <= 0) {
      startWave();
      state = 'playing';
    }
  }
}

function endGame() {
  state = 'gameover';
  crosshairGroup.visible = false;
  audio.stopMusic();
  audio.gameOver();

  save.gamesPlayed++;
  if (score > save.bestScore) save.bestScore = score;
  if (wave > save.bestWave) save.bestWave = wave;
  save.totalScore += score;
  if (mode === 'survival' && wave > save.survivalBest) save.survivalBest = wave;
  if (mode === 'blitz' && score > save.blitzBest) save.blitzBest = score;

  addXp(score / 10);

  // Leaderboard
  save.leaderboard.push({ score, wave, mode, date: new Date().toISOString().slice(0, 10) });
  save.leaderboard.sort((a, b) => b.score - a.score);
  if (save.leaderboard.length > 20) save.leaderboard.length = 20;

  checkAchievements();
  saveSave(save);
}

// ─── MOUSE INPUT SYSTEM ─────────────────────────────────
export class CommandInputSystem extends createSystem({}) {
  private clicked = false;
  private lastClickTime = 0;

  update(delta: number, time: number) {
    if (state !== 'playing') return;

    // Update crosshair from mouse
    const rect = world.renderer.domElement.getBoundingClientRect();
    const ndcX = (mouseX / rect.width) * 2 - 1;
    const ndcY = -(mouseY / rect.height) * 2 + 1;
    raycaster.setFromCamera(new Vector2(ndcX, ndcY), world.camera);
    const hits = raycaster.intersectObject(targetPlane);
    if (hits.length > 0) {
      const pt = hits[0].point;
      crosshairGroup.position.set(
        Math.max(-5.5, Math.min(5.5, pt.x)),
        Math.max(GROUND_Y + 0.3, Math.min(SKY_Y + 1, pt.y)),
        PLAY_Z
      );
    }

    // Crosshair pulse
    const pulse = 0.9 + Math.sin(time * 4) * 0.1;
    chRing.scale.setScalar(pulse);

    // XR controller input
    const input = this.input;
    if (input) {
      const trigger = input.getButtonDown?.(InputComponent.Trigger);
      if (trigger) {
        const cx = crosshairGroup.position.x;
        const cy = crosshairGroup.position.y;
        if (cy > GROUND_Y + 0.5) {
          fireCounterMissile(cx, cy);
        }
      }
    }
  }
}

// Mouse event listeners
world.renderer.domElement.addEventListener('mousemove', (e: MouseEvent) => {
  mouseX = e.clientX;
  mouseY = e.clientY;
});

world.renderer.domElement.addEventListener('click', (e: MouseEvent) => {
  if (state !== 'playing') return;
  mouseX = e.clientX;
  mouseY = e.clientY;
  // Update crosshair position first
  const rect = world.renderer.domElement.getBoundingClientRect();
  const ndcX = (mouseX / rect.width) * 2 - 1;
  const ndcY = -(mouseY / rect.height) * 2 + 1;
  raycaster.setFromCamera(new Vector2(ndcX, ndcY), world.camera);
  const hits = raycaster.intersectObject(targetPlane);
  if (hits.length > 0) {
    const pt = hits[0].point;
    const cx = Math.max(-5.5, Math.min(5.5, pt.x));
    const cy = Math.max(GROUND_Y + 0.3, Math.min(SKY_Y + 1, pt.y));
    crosshairGroup.position.set(cx, cy, PLAY_Z);
    if (cy > GROUND_Y + 0.5) {
      fireCounterMissile(cx, cy);
    }
  }
});

// Keyboard shortcuts
document.addEventListener('keydown', (e: KeyboardEvent) => {
  if (e.key === 'Escape' || e.key === 'p') {
    if (state === 'playing') { state = 'pause'; audio.stopMusic(); }
    else if (state === 'pause') { state = 'playing'; audio.startMusic(); }
  }
  if (e.key === 'r' && state === 'gameover') {
    startNewGame(mode, difficulty);
  }
});

// ─── UI SYSTEM ───────────────────────────────────────────
const panelConfigs = [
  'title', 'modeselect', 'difficulty', 'hud', 'pause', 'gameover',
  'waveclear', 'leaderboard', 'achievements', 'settings', 'help',
  'skins', 'stats', 'toast', 'countdown',
];

// Create panel entities
for (const name of panelConfigs) {
  const entity = world.createTransformEntity();
  entity.addComponent(PanelUI, { config: `./ui/${name}.json` });
  if (name === 'hud' || name === 'toast' || name === 'countdown') {
    entity.addComponent(Follower);
    const fv = entity.getVectorView(Follower, 'offsetPosition');
    if (name === 'hud') { fv[0] = 0; fv[1] = -0.15; fv[2] = -0.6; }
    else if (name === 'toast') { fv[0] = 0; fv[1] = 0.15; fv[2] = -0.6; }
    else { fv[0] = 0; fv[1] = 0; fv[2] = -0.5; }
    entity.addComponent(ScreenSpace);
  }
}

const getDoc = (e: any) => e.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
const setText = (e: any, id: string, text: string) => (getDoc(e)?.getElementById(id) as UIKit.Text | undefined)?.setProperties({ text });
const setVis = (e: any, id: string, vis: boolean) => (getDoc(e)?.getElementById(id) as UIKit.Text | undefined)?.setProperties({ display: vis ? 'flex' : 'none' });

function startNewGame(m: GameMode, d: Difficulty) {
  mode = m;
  difficulty = d;
  audio.init(save.masterVol, save.sfxVol, save.musicVol);
  setupGame();
  countdownTimer = 3;
  countdownVal = 3;
  state = 'title'; // Technically in countdown
}

export class CommandUISystem extends createSystem({
  title: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/title.json')] },
  modeselect: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/modeselect.json')] },
  diffPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/difficulty.json')] },
  hud: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/hud.json')] },
  pause: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/pause.json')] },
  gameover: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/gameover.json')] },
  waveclear: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/waveclear.json')] },
  lb: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/leaderboard.json')] },
  ach: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/achievements.json')] },
  settings: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/settings.json')] },
  helpPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/help.json')] },
  skinsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/skins.json')] },
  statsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/stats.json')] },
  toastPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/toast.json')] },
  countdownPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/countdown.json')] },
}) {
  private bound = new Set<string>();
  private achPage = 0;

  init() {
    const panels = ['title', 'modeselect', 'diffPanel', 'hud', 'pause', 'gameover', 'waveclear', 'lb', 'ach', 'settings', 'helpPanel', 'skinsPanel', 'statsPanel', 'toastPanel', 'countdownPanel'] as const;
    for (const p of panels) {
      this.queries[p].subscribe('qualify', (entity: any) => {
        this.bindPanel(p, entity);
      });
    }
  }

  private bindPanel(name: string, entity: any) {
    if (this.bound.has(name)) return;
    this.bound.add(name);
    const doc = getDoc(entity);
    if (!doc) return;

    const btn = (id: string, fn: () => void) => {
      const el = doc.getElementById(id) as UIKit.Text | undefined;
      el?.addEventListener('click', () => { audio.click(); fn(); });
    };

    switch (name) {
      case 'title':
        btn('btn-play', () => { state = 'modeselect'; });
        btn('btn-scores', () => { state = 'leaderboard'; this.updateLeaderboard(); });
        btn('btn-achievements', () => { state = 'achievements'; this.achPage = 0; this.updateAchievements(); });
        btn('btn-stats', () => { state = 'stats'; this.updateStats(); });
        btn('btn-skins', () => { state = 'skins'; this.updateSkins(); });
        btn('btn-settings', () => { state = 'settings'; this.updateSettings(); });
        btn('btn-help', () => { state = 'help'; });
        break;
      case 'modeselect':
        for (const m of MODES) {
          btn('btn-' + m.id, () => { mode = m.id; state = 'difficulty'; });
        }
        btn('btn-back', () => { state = 'title'; });
        break;
      case 'diffPanel':
        btn('btn-easy', () => { difficulty = 'easy'; startNewGame(mode, 'easy'); });
        btn('btn-medium', () => { difficulty = 'medium'; startNewGame(mode, 'medium'); });
        btn('btn-hard', () => { difficulty = 'hard'; startNewGame(mode, 'hard'); });
        btn('btn-back', () => { state = 'modeselect'; });
        break;
      case 'pause':
        btn('btn-resume', () => { state = 'playing'; audio.startMusic(); });
        btn('btn-quit', () => { state = 'title'; audio.stopMusic(); });
        break;
      case 'gameover':
        btn('btn-rematch', () => { startNewGame(mode, difficulty); });
        btn('btn-menu', () => { state = 'title'; });
        break;
      case 'lb':
        btn('btn-back', () => { state = 'title'; });
        break;
      case 'ach':
        btn('btn-back', () => { state = 'title'; });
        btn('btn-prev', () => { if (this.achPage > 0) { this.achPage--; this.updateAchievements(); } });
        btn('btn-next', () => { if ((this.achPage + 1) * 15 < ACHIEVEMENTS.length) { this.achPage++; this.updateAchievements(); } });
        break;
      case 'settings':
        btn('btn-master-up', () => { save.masterVol = Math.min(1, save.masterVol + 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-master-dn', () => { save.masterVol = Math.max(0, save.masterVol - 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-sfx-up', () => { save.sfxVol = Math.min(1, save.sfxVol + 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-sfx-dn', () => { save.sfxVol = Math.max(0, save.sfxVol - 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-music-up', () => { save.musicVol = Math.min(1, save.musicVol + 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-music-dn', () => { save.musicVol = Math.max(0, save.musicVol - 0.1); audio.setVolumes(save.masterVol, save.sfxVol, save.musicVol); saveSave(save); this.updateSettings(); });
        btn('btn-theme-prev', () => { save.theme = (save.theme - 1 + THEMES.length) % THEMES.length; theme = THEMES[save.theme]; saveSave(save); this.updateSettings(); });
        btn('btn-theme-next', () => { save.theme = (save.theme + 1) % THEMES.length; theme = THEMES[save.theme]; saveSave(save); this.updateSettings(); });
        btn('btn-back', () => { state = 'title'; });
        break;
      case 'helpPanel':
        btn('btn-back', () => { state = 'title'; });
        break;
      case 'skinsPanel':
        for (let i = 0; i < SKINS.length; i++) {
          btn('btn-skin-' + i, () => {
            if (SKINS[i].check(save)) { save.skin = i; skinIdx = i; saveSave(save); this.updateSkins();
              (chRing.material as MeshBasicMaterial).color.set(SKINS[i].color);
              (chDot.material as MeshBasicMaterial).color.set(SKINS[i].color);
            }
          });
        }
        btn('btn-back', () => { state = 'title'; });
        break;
      case 'statsPanel':
        btn('btn-back', () => { state = 'title'; });
        break;
    }
  }

  private updateLeaderboard() {
    this.queries.lb.entities.forEach((e: any) => {
      for (let i = 0; i < 10; i++) {
        const entry = save.leaderboard[i];
        setText(e, 'lb-' + i, entry ? `${i + 1}. ${entry.score} - ${entry.mode} - W${entry.wave} - ${entry.date}` : `${i + 1}. ---`);
      }
    });
  }

  private updateAchievements() {
    this.queries.ach.entities.forEach((e: any) => {
      const start = this.achPage * 15;
      for (let i = 0; i < 15; i++) {
        const a = ACHIEVEMENTS[start + i];
        if (a) {
          const done = save.achievements.includes(a.id);
          setText(e, 'ach-' + i, `${done ? '[X]' : '[ ]'} ${a.name} - ${a.desc}`);
        } else {
          setText(e, 'ach-' + i, '');
        }
      }
      setText(e, 'page-info', `${this.achPage + 1}/${Math.ceil(ACHIEVEMENTS.length / 15)}`);
    });
  }

  private updateSettings() {
    this.queries.settings.entities.forEach((e: any) => {
      setText(e, 'master-val', `${Math.round(save.masterVol * 100)}%`);
      setText(e, 'sfx-val', `${Math.round(save.sfxVol * 100)}%`);
      setText(e, 'music-val', `${Math.round(save.musicVol * 100)}%`);
      setText(e, 'theme-val', theme.name);
    });
  }

  private updateSkins() {
    this.queries.skinsPanel.entities.forEach((e: any) => {
      for (let i = 0; i < SKINS.length; i++) {
        const s = SKINS[i];
        const unlocked = s.check(save);
        const equipped = i === save.skin;
        setText(e, 'skin-name-' + i, s.name);
        setText(e, 'skin-status-' + i, equipped ? 'EQUIPPED' : unlocked ? 'AVAILABLE' : s.unlockDesc);
      }
    });
  }

  private updateStats() {
    this.queries.statsPanel.entities.forEach((e: any) => {
      setText(e, 'stat-0', `Games Played: ${save.gamesPlayed}`);
      setText(e, 'stat-1', `Best Score: ${save.bestScore}`);
      setText(e, 'stat-2', `Total Score: ${save.totalScore}`);
      setText(e, 'stat-3', `Best Wave: ${save.bestWave}`);
      setText(e, 'stat-4', `Total Interceptions: ${save.totalInterceptions}`);
      setText(e, 'stat-5', `Cities Saved: ${save.citiesSaved}`);
      setText(e, 'stat-6', `Perfect Waves: ${save.perfectWaves}`);
      setText(e, 'stat-7', `Best Multi-Kill: ${save.bestMultiKill}`);
      setText(e, 'stat-8', `Level: ${save.level}`);
      setText(e, 'stat-9', `XP: ${save.xp}/${100 + save.level * 50}`);
    });
  }

  update() {
    // Show/hide panels based on state
    const visMap: Record<string, GameState[]> = {
      title: ['title'],
      modeselect: ['modeselect'],
      diffPanel: ['difficulty'],
      hud: ['playing', 'waveclear'],
      pause: ['pause'],
      gameover: ['gameover'],
      waveclear: ['waveclear'],
      lb: ['leaderboard'],
      ach: ['achievements'],
      settings: ['settings'],
      helpPanel: ['help'],
      skinsPanel: ['skins'],
      statsPanel: ['stats'],
    };

    for (const [qName, states] of Object.entries(visMap)) {
      const show = states.includes(state) || (countdownTimer > 0 && qName === 'title' && state === 'title');
      this.queries[qName as keyof typeof this.queries]?.entities?.forEach((e: any) => {
        const obj = e.object3D as Object3D | undefined;
        if (obj) obj.visible = show && !states.includes('title' as GameState) || (states.includes(state));
      });
    }

    // Show panels by visibility
    for (const [qName, states] of Object.entries(visMap)) {
      const show = states.includes(state);
      (this.queries as any)[qName]?.entities?.forEach((e: any) => {
        const obj = e.object3D as Object3D | undefined;
        if (obj) obj.visible = show;
      });
    }

    // Countdown panel
    this.queries.countdownPanel.entities.forEach((e: any) => {
      const obj = e.object3D as Object3D | undefined;
      if (obj) obj.visible = countdownTimer > 0;
      if (countdownTimer > 0) {
        setText(e, 'countdown-text', countdownVal <= 0 ? 'DEFEND!' : String(countdownVal));
      }
    });

    // Toast panel
    this.queries.toastPanel.entities.forEach((e: any) => {
      const obj = e.object3D as Object3D | undefined;
      if (obj) obj.visible = toastTimer > 0;
      if (toastTimer > 0) setText(e, 'toast-text', toastText);
    });

    // HUD updates
    if (state === 'playing' || state === 'waveclear') {
      this.queries.hud.entities.forEach((e: any) => {
        setText(e, 'score', `Score: ${score}`);
        setText(e, 'wave', `Wave: ${wave}`);
        const alive = cities.filter(c => c.alive).length;
        setText(e, 'cities', `Cities: ${alive}/6`);
        const totalAmmo = bases.reduce((s, b) => s + b.ammo, 0);
        setText(e, 'ammo', `Ammo: ${totalAmmo}`);
        if (mode === 'blitz') setText(e, 'time', `Time: ${Math.ceil(blitzTimer)}s`);
        else setText(e, 'time', `Mode: ${mode}`);
      });
    }

    // Game over updates
    if (state === 'gameover') {
      this.queries.gameover.entities.forEach((e: any) => {
        setText(e, 'final-score', `Score: ${score}`);
        setText(e, 'final-wave', `Waves: ${wave}`);
        const alive = cities.filter(c => c.alive).length;
        setText(e, 'final-cities', `Cities Saved: ${alive}`);
        setText(e, 'final-intercepts', `Interceptions: ${save.totalInterceptions}`);
        setText(e, 'final-mode', `Mode: ${mode}`);
      });
    }

    // Wave clear updates
    if (state === 'waveclear') {
      this.queries.waveclear.entities.forEach((e: any) => {
        const alive = cities.filter(c => c.alive).length;
        setText(e, 'wave-num', `Wave ${wave} Clear!`);
        setText(e, 'city-bonus', `City Bonus: ${alive * 100}`);
        const ammoBonus = bases.reduce((s, b) => s + b.ammo, 0) * 5;
        setText(e, 'ammo-bonus', `Ammo Bonus: ${ammoBonus}`);
      });
    }

    // Title level display
    this.queries.title.entities.forEach((e: any) => {
      setText(e, 'level-display', `Level ${save.level} -- XP: ${save.xp}/${100 + save.level * 50}`);
    });
  }
}

